function obj_index(npc, tbl)
	if npc == nil or npc <= 0 then return 0 end
	local m, x, y = GetNpcPos(npc)
	local i = 1
	while tbl[i] do
		if abs(tbl[i][1] - x) <= 2 and abs(tbl[i][2] - y) <= 2 then return i end
		i = i + 1
	end
	return 0
end

function main(npc)
	local tpl = 0
	if npc and npc > 0 then tpl = GetNpcTemplateID(npc) end
	if tpl == 874 then
		lt_main()
	elseif tpl == 792 or tpl == 793 then
		fl_main(npc, tpl)
	else
		lamp_main(npc)
	end
end

function lamp_main(npc)
	local i = obj_index(npc, PTTM_LAMPS)
	local m = GetTask(PTTM_T_MAIN)
	local side = 1
	if i > 6 then side = 2 end
	local want = 0
	if side == 1 and (m == 9 or m == 11) then want = 1 end
	if side == 2 and (m == 16 or m == 18) then want = 1 end
	if i == 0 or want == 0 then
		Talk(1, "", "<color=green>Liªn Hoa ThÇn §¨ng<color>: Ngän ®Ìn hoa sen táa ¸nh s¸ng mê nh¹t.")
		return
	end
	local k = i
	if side == 2 then k = i - 6 end
	local b, j = 1, 1
	while j < k do
		b = b * 2
		j = j + 1
	end
	local mk = PTTM_Get(F_LAMP)
	if PTTM_Bit(mk, b) == 1 then
		Talk(1, "", "<color=green>Liªn Hoa ThÇn §¨ng<color>: Ngän ®Ìn nµy ®· ®­îc ng­¬i th¾p s¸ng.")
		return
	end
	mk = mk + b
	PTTM_Set(F_LAMP, mk)
	local c, bb = 0, 1
	while bb <= 32 do
		if PTTM_Bit(mk, bb) == 1 then c = c + 1 end
		bb = bb * 2
	end
	if c >= 6 then
		Msg2Player("C¶ 6 ngän <color=yellow>Liªn Hoa ThÇn §¨ng<color> ®· s¸ng! VÒ gÆp Liªn §¨ng Hé Sø gäi Liªn §¨ng Sø Gi¶.")
	else
		Msg2Player(format("Th¾p s¸ng Liªn Hoa ThÇn §¨ng %d/6.", c))
	end
end

