-- flowers: 1023/1028 (8 of the own kind) and 97 Ly (Man Chau Sa) / Chan (Man Da La)
function fl_main(npc, tpl)
	local i = obj_index(npc, PTTM_FLOWERS)
	local fn = "M¹n §µ La Hoa"
	if tpl == 793 then fn = "M¹n Ch©u Sa Hoa" end
	local q = 0
	local s = PTTM_Get(F_1023S)
	if s == 1 and ((tpl == 792 and not PTTM_IsMa()) or (tpl == 793 and PTTM_IsMa())) then q = 1 end
	local g = 0
	if GetTaskByte(PTTM_T_GUA, 3) == 2 then
		local gg = GetTaskByte(PTTM_T_GUA, 4)
		if (gg == 3 and tpl == 793) or (gg == 4 and tpl == 792) then g = gg end
	end
	if i == 0 or (q == 0 and g == 0) then
		Talk(1, "", "<color=green>" .. fn .. "<color>: §ãa hoa ch­a në d­íi bãng c©y.")
		return
	end
	Say("<color=green>" .. fn .. "<color>: §ãa hoa ch­a në, cÇn Cam Lé míi tr­ëng thµnh.", 2, "T­íi Cam Lé vµ h¸i hoa/fl_pick" .. i, "KÕt thóc ®èi tho¹i/no")
end

function fl_pick(i)
	local p = PTTM_FLOWERS[i]
	if p == nil then return end
	local tpl = p[3]
	local b, j = 1, 1
	while j < i do
		b = b * 2
		j = j + 1
	end
	local mk = PTTM_Get(F_FLOWER)
	if PTTM_Bit(mk, b) == 1 then
		Talk(1, "", "§ãa hoa nµy ng­¬i võa h¸i råi, h·y t×m ®ãa kh¸c.")
		return
	end
	-- all flowers of this kind picked: start a new pass
	local first, last = 1, 8
	if tpl == 793 then first, last = 9, 16 end
	local c, k, bb = 0, 1, 1
	while k <= 16 do
		if k >= first and k <= last and PTTM_Bit(mk, bb) == 1 then c = c + 1 end
		bb = bb * 2
		k = k + 1
	end
	if c >= 7 then
		k, bb = 1, 1
		while k <= 16 do
			if k >= first and k <= last and PTTM_Bit(mk, bb) == 1 then mk = mk - bb end
			bb = bb * 2
			k = k + 1
		end
	end
	mk = mk + b
	PTTM_Set(F_FLOWER, mk)
	local fn = "M¹n §µ La Hoa"
	if tpl == 793 then fn = "M¹n Ch©u Sa Hoa" end
	local got = 0
	if PTTM_Get(F_1023S) == 1 and ((tpl == 792 and not PTTM_IsMa()) or (tpl == 793 and PTTM_IsMa())) then
		local n = PTTM_Cnt(F_1023C, 8)
		got = 1
		if n >= 8 then
			PTTM_Set(F_1023S, 2)
			Msg2Player("§· h¸i ®ñ 8 ®ãa " .. fn .. ", vÒ phôc mÖnh <color=yellow>Tu Hµnh S­<color>!")
		else
			Msg2Player(format("H¸i ®­îc %d/8 ®ãa ", n) .. fn .. ".")
		end
	end
	if GetTaskByte(PTTM_T_GUA, 3) == 2 then
		local gg = GetTaskByte(PTTM_T_GUA, 4)
		if (gg == 3 and tpl == 793) or (gg == 4 and tpl == 792) then
			PTTM_GuaStep(gg)
			got = 1
		end
	end
	if got == 0 then
		Talk(1, "", "Ng­¬i kh«ng cÇn h¸i hoa lóc nµy.")
	end
end
